n = 15
edges = []
for i in range(n):
    for j in range(1, 7):
        v = (i + j) % n
        if i < v:
            edges.append((i, v))
edges = sorted(set(edges))
degrees = [0]*n
for u,v in edges:
    degrees[u] += 1
    degrees[v] += 1
print("Degrees:", degrees)
print("Min degree:", min(degrees))
print("Max degree:", max(degrees))
# Check each vertex
for i in range(n):
    neighbors = []
    for u,v in edges:
        if u == i:
            neighbors.append(v)
        elif v == i:
            neighbors.append(u)
    print(f"Vertex {i}: degree={len(neighbors)}, neighbors={sorted(neighbors)}")
